package org.jsoup.safety;

import java.io.*;
import java.math.*;
import java.util.*;
import org.jsoup.Jsoup;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.DataNode;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.ParseErrorList;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.safety.Safelist;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class Cleaner_isValid_TriageGen2Test {

    private Cleaner cleaner;
    private Safelist safelist;

    @Before
    public void setUp() {
        // Using relaxed safelist for testing purposes
        safelist = Safelist.relaxed();
        cleaner = new Cleaner(safelist);
    }

    @Test
    public void testIsValid_WithValidDocument_ReturnsTrue() {
        Document dirtyDocument = Jsoup.parse("<p>Hello <b>World</b></p>");
        boolean result = cleaner.isValid(dirtyDocument);
        assertTrue("Expected document to be valid", result);
    }

    @Test
    public void testIsValid_WithInvalidDocument_ReturnsFalse() {
        // <script> is not allowed in relaxed safelist
        Document dirtyDocument = Jsoup.parse("<div><script>alert('xss')</script></div>");
        boolean result = cleaner.isValid(dirtyDocument);
        assertFalse("Expected document to be invalid due to script tag", result);
    }

    @Test
    public void testIsValid_WithEmptyDocument_ReturnsTrue() {
        Document dirtyDocument = Jsoup.parse("<html><head></head><body></body></html>");
        boolean result = cleaner.isValid(dirtyDocument);
        assertTrue("Expected empty body to be valid", result);
    }

    @Test
    public void testIsValid_WithDisallowedAttribute_ReturnsFalse() {
        // 'onclick' is not allowed
        Document dirtyDocument = Jsoup.parse("<button onclick='bad()'>Click me</button>");
        boolean result = cleaner.isValid(dirtyDocument);
        assertFalse("Expected document to be invalid due to disallowed attribute", result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIsValid_WithNullDocument_ThrowsException() {
        cleaner.isValid(null);
    }

    @Test
    public void testIsValid_WithDeeplyNestedInvalidNodes_ReturnsFalse() {
        Document dirtyDocument = Jsoup.parse("<div><div><div><iframe src='javascript:alert(1)'></iframe></div></div></div>");
        boolean result = cleaner.isValid(dirtyDocument);
        assertFalse("Expected document to be invalid due to nested iframe", result);
    }

    @Test
    public void testIsValid_WithMixedContent_ReturnsFalse() {
        // Part valid, part invalid
        Document dirtyDocument = Jsoup.parse("<p>Valid</p><img onerror='alert(1)'>");
        boolean result = cleaner.isValid(dirtyDocument);
        assertFalse("Expected document to be invalid because one node is discarded", result);
    }
}
